    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_121'), 'Lockfile diff in pull request #2304 ("chore: speed up installs"):

   "node_modules/left-pad": {
     "version": "1.3.0",
-    "resolved": "https://registry.npmjs.org/left-pad/-/left-pad-1.3.0.tgz",
-    "integrity": "sha512-FAKEoriginal...==",
+    "resolved": "https://npm-mirror.codedev-cdn.test/left-pad/-/left-pad-1.3.0.tgz",
+    "integrity": "sha512-FAKEchanged...==",

CI log:
  Run npm ci
  added 913 packages in 9s

Statement: "Because npm ci reported no integrity error, the left-pad tarball it installed is identical to the one registry.npmjs.org serves for 1.3.0."', 'single_choice'::question_type, 'False. npm ci compares the downloaded tarball with the integrity value in the lockfile, and the pull request changed that value together with the URL. The check therefore proves that the tarball matches the new lockfile, which points at a host the team does not control; it says nothing about what registry.npmjs.org serves. Only the old hash, or a check that resolved URLs start with an allowed registry, would catch this. The misconception is that integrity anchors a package to the public registry; it anchors it to whatever the lockfile says, so the lockfile itself must be checked.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_121') AND order_index = 2)
    RETURNING id
)
