-- challenge chal_coding_ssc_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_122', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-1-2' AND is_deleted = false LIMIT 1), 'lockfile-check', 'Check the lockfile before npm ci', 'CI for the CodeDev web app runs npm ci, which installs exactly what package-lock.json says - so the lockfile itself must be checked first. Write checkLockfile(manifest, lock, policy) in TypeScript. It returns findings { kind, package, detail }. missing: a name from dependencies or devDependencies has no "node_modules/<name>" entry with a version in lock.packages; detail = the spec. wide-range: the spec parses but has no upper bound (detail "<spec> (no upper bound)"), or it is outside the range subset below (detail "<spec> (not a version range)": dist-tags such as latest, git and URL specs, ||, hyphen ranges, ^1.2, v1.2.3 ...). mismatch: the locked version does not satisfy the spec; only checked when the spec parses and has an upper bound; detail "<spec> but locked <version>". A spec can give both wide-range and missing. registry: an installed package - every key of packages that contains "node_modules/", except entries with link: true - whose resolved is missing (detail "no resolved URL") or does not start with one of policy.allowedRegistries (detail = the URL). integrity: an installed package whose integrity is missing or empty; detail "missing". For registry and integrity, package = the key without a leading "node_modules/" ("express/node_modules/qs"). Range subset (spaces around a spec are ignored): "*", "x", "X" or "" = any version, no upper bound; 1.2.3 = exactly that version; 1.2, 1.2.x, 1.2.* = >=1.2.0 <1.3.0; 1, 1.x, 1.x.x, 1.* = >=1.0.0 <2.0.0; ^1.2.3 = >=1.2.3 <2.0.0, ^0.2.3 = >=0.2.3 <0.3.0, ^0.0.3 = >=0.0.3 <0.0.4; ~1.2.3 = >=1.2.3 <1.3.0 (^ and ~ need a full MAJOR.MINOR.PATCH); one or two comparators separated by spaces, each >=, >, <= or < followed by a full version, at most one lower (>=, >) and one upper (<=, <) bound, in any order. Version numbers are plain digits. A locked version with a prerelease (2.0.0-rc.1) never satisfies a range of this subset. Sort the findings by package (plain string comparison), then by kind in the order missing, wide-range, mismatch, registry, integrity. If lockfileVersion is not 2 or 3, return only { kind: "unsupported-lockfile", package: "package-lock.json", detail: "lockfileVersion <value>" } ("lockfileVersion missing" when absent); if the version is 2 or 3 but packages is missing, the detail is "no packages map". A name appears in at most one of dependencies and devDependencies. The runner prints one line per finding, then the count.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_122');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_122'), 1, 'For each dependency there are three separate questions: is there a lock entry, does the policy accept the spec, and does the locked version fall inside it? Which of them can you still answer when the spec is "latest" or a git URL - and which findings come from the lock entries alone, without looking at package.json?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_122'), 2, 'Turn every spec into a lower and an upper bound, each with an inclusive flag, or into null when it is outside the subset; "no upper bound" and "null" both become wide-range findings with different details. Then satisfies(version, range) is two comparisons of [major, minor, patch] tuples, after rejecting versions that are not plain digits. For hosts, startsWith against the whole allowed prefix, trailing slash included.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_122'), 3, 'A worked example on other data: ~3.4.1 gives lower 3.4.1 inclusive and upper 3.5.0 exclusive, so 3.4.9 satisfies it while 3.5.0 and 3.4.0 do not. ^0.5.2 gives upper 0.6.0 exclusive, so 0.9.0 is a mismatch. >=5.0.0 parses but has no upper bound; 5.0.0 || 6.0.0 does not parse. A lock entry resolved from http://registry.npmjs.org/... fails an allowed prefix of https://registry.npmjs.org/ because the scheme differs. Two findings for the package "zod" print wide-range before mismatch; "@a/b" sorts before "a".');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_122'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
