-- challenge chal_quiz_ssc_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ssc_131', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-1-3' AND is_deleted = false LIMIT 1), 'allowlist-quarantine-quiz', 'Who approved this name, and how old is this version?', 'Two pieces of evidence from the CodeDev dependency gate: an allowlist matcher with a wildcard entry, and an exception for an urgent security release.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_131'), 'The gate''s allowlist matcher, written by an AI assistant:

const allowlist = ["@codedev/*", "lodash*", "zod"];
const allowed = (name: string) =>
  allowlist.some((p) => p.endsWith("*") ? name.startsWith(p.slice(0, -1)) : name === p);

Policy: quarantineDays 7. Today is 2026-10-27.
Pull request #2331 adds lodash-deep-clone-pro 1.0.3, published 2026-10-18T09:00:00Z by an account created the same day.

Statement: "The gate blocks lodash-deep-clone-pro in pull request #2331."', 'single_choice'::question_type, 'False. For "lodash*" the matcher drops the star and checks name.startsWith("lodash"), which lodash-deep-clone-pro passes. The version is 9 days old, so the 7-day quarantine ends on 2026-10-25 and does not block it either: the package is allowed. A wildcard is safe only for a scope you own, because only your organization can publish under @codedev/; anyone can register a name that starts with lodash. The misconception is that a prefix pattern restricts names the way a scope does; replace it with the exact names you approved (lodash, lodash.merge ...).', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_131'), 'dependency-policy.json:
{
  "allowlist": ["@codedev/*", "express", "zod", "next"],
  "quarantineDays": 7,
  "exceptions": [
    { "name": "express", "version": "4.22.1", "ticket": "SEC-231", "expires": "2026-11-03" }
  ]
}

Registry snapshot: express 4.22.1 published 2026-10-26T15:02:00Z (fix for an advisory that affects the API).
Today is 2026-10-27. The gate lifts the allowlist and quarantine blocks for a change whose name and exact version match an exception that has not expired.

Statement: "Today the gate allows express 4.22.1, and if 4.22.2 is published tomorrow, the gate blocks it until its own quarantine ends."', 'single_choice'::question_type, 'True. 4.22.1 is one day old, so the quarantine alone would block it until 2026-11-02, but the exception matches the name and the exact version and is valid until 2026-11-03, so the gate allows it. The exception says nothing about 4.22.2: a release tomorrow is checked like any other version and waits 7 days. That is the reason exceptions name an exact version - an exception for "express" in general would also have let through a hijacked release published right after the fix. The misconception is that an exception approves a package; it approves one decision about one version, for a limited time.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_ssc_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_132', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-1-3' AND is_deleted = false LIMIT 1), 'dependency-allowlist-gate', 'Gate new dependencies: allowlist, quarantine and exceptions', 'Every pull request to the CodeDev repositories passes a dependency gate before npm ci. Write decide(change, policy, registry, today) in TypeScript: it returns { allow, reasons } for one added or updated package (change.name and the new version change.to; from is only displayed). Blocking reasons, in this order: "not in registry" - registry (name -> version -> publish timestamp) has no such package or no such version; "publish date unknown" - the timestamp is not ISO 8601 with a date, a time (hh:mm, optional :ss and fraction) and Z or an offset such as +07:00 (2026-10-20T08:15:00Z, 2026-10-21T03:00:00+07:00); "not on allowlist" - no allowlist entry matches: an entry matches the exact name (case-sensitive), and an entry of the form "@scope/*" matches every name that starts with "@scope/"; "quarantined until <D> (published <P>)" - P is the UTC calendar date (YYYY-MM-DD) of the publish instant, D is P plus policy.quarantineDays days, and the version is blocked while today < D (today is a YYYY-MM-DD date; dates in this form compare correctly as strings). An exception { name, version, ticket, expires } matches a change with the same name and exact version; it is valid while expires is a real calendar date written YYYY-MM-DD and today <= expires. A valid exception lifts "not on allowlist" and the quarantine, but never "not in registry" or "publish date unknown"; when it turns a block into an allow, reasons is ["exception <ticket> (expires <expires>)"] for the first valid matching exception in the list. When the change stays blocked and matching exceptions exist but none of them is valid, add "exception <ticket> not valid (expires <expires>)" for the first matching one, as the last reason. A change with no blocking reason is allowed with reasons []. The runner prints one line per change, in input order, then the totals.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 1, 'Which blocking reasons describe facts about the package (does this version exist, can we read its date) and which describe your team''s decisions (an approved name, a waiting period)? Which of the two kinds can a signed-off exception change?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 2, 'Collect the reasons in two lists - the ones an exception may lift and the ones it may not - and look at exceptions only at the end. For dates: check the timestamp format with a regular expression before Date.parse (which accepts many other formats), take new Date(ms).toISOString().slice(0, 10) for the UTC date, add days in milliseconds from that date''s midnight UTC, and compare YYYY-MM-DD strings. A real date survives the round trip through Date and toISOString unchanged.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 3, 'A worked example on other data, quarantine 3 days, today 2026-03-10: a version published 2026-03-07T22:00:00-05:00 is 2026-03-08T03:00:00Z, so P = 2026-03-08 and D = 2026-03-11: blocked. One published 2026-03-07T10:00:00Z gives D = 2026-03-10: allowed, because today is not before D. An entry @acme/* allows @acme/cli but not @acme-tools/cli or acme-cli. An exception that expires 2026-03-10 still counts on 2026-03-10; one for version 2.0.0 does nothing for 2.0.1.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'The AI pull request: an unknown name, a lookalike, a two-day-old zod; express and our scope pass', '{"today":"2026-10-27","policy":{"allowlist":["@codedev/*","express","zod","marked","dompurify","pino","next","react","react-dom"],"quarantineDays":7,"exceptions":[]},"registry":{"express":{"4.21.1":"2024-10-08T19:42:11Z","4.21.2":"2024-12-05T17:20:31Z","4.22.0":"2026-10-25T09:00:00Z"},"zod":{"4.1.11":"2026-09-22T12:00:00Z","4.1.12":"2026-10-25T06:30:00Z"},"marked":{"14.1.2":"2026-08-01T10:00:00Z","14.1.3":"2026-10-19T10:00:00Z"},"dompurify":{"3.2.7":"2026-09-30T08:00:00Z"},"dom-purify":{"3.1.0":"2026-10-17T03:12:41Z"},"@codedev/md-render":{"0.3.0":"2026-09-30T14:00:00Z","0.4.0":"2026-10-26T16:00:00Z"},"left-pad":{"1.3.0":"2018-04-09T00:00:00Z"},"pino":{"9.12.0":"2026-10-23T11:00:00Z","9.12.1":"2026-10-24T11:00:00Z"}},"changes":[{"name":"marked","from":null,"to":"14.1.2"},{"name":"dom-purify","from":null,"to":"3.1.0"},{"name":"markdown-sanitize-lite","from":null,"to":"1.0.0"},{"name":"zod","from":"4.1.11","to":"4.1.12"},{"name":"@codedev/md-render","from":null,"to":"0.3.0"},{"name":"express","from":"4.21.1","to":"4.21.2"}]}', '"allow marked@14.1.2\nblock dom-purify@3.1.0: not on allowlist\nblock markdown-sanitize-lite@1.0.0: not in registry; not on allowlist\nblock zod@4.1.12 (was 4.1.11): quarantined until 2026-11-01 (published 2026-10-25)\nallow @codedev/md-render@0.3.0\nallow express@4.21.2 (was 4.21.1)\n3 allowed, 3 blocked"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'Exceptions: one for the exact version lifts quarantine; an expired one and another version do not', '{"today":"2026-10-27","policy":{"allowlist":["@codedev/*","express","zod","marked","dompurify","pino","next","react","react-dom"],"quarantineDays":7,"exceptions":[{"name":"zod","version":"4.1.12","ticket":"SEC-212","expires":"2026-11-03"},{"name":"left-pad","version":"1.3.0","ticket":"SEC-118","expires":"2026-10-20"},{"name":"pino","version":"9.12.0","ticket":"SEC-230","expires":"2026-11-10"},{"name":"@codedev/md-render","version":"0.3.0","ticket":"SEC-199","expires":"2026-12-01"}]},"registry":{"express":{"4.21.1":"2024-10-08T19:42:11Z","4.21.2":"2024-12-05T17:20:31Z","4.22.0":"2026-10-25T09:00:00Z"},"zod":{"4.1.11":"2026-09-22T12:00:00Z","4.1.12":"2026-10-25T06:30:00Z"},"marked":{"14.1.2":"2026-08-01T10:00:00Z","14.1.3":"2026-10-19T10:00:00Z"},"dompurify":{"3.2.7":"2026-09-30T08:00:00Z"},"dom-purify":{"3.1.0":"2026-10-17T03:12:41Z"},"@codedev/md-render":{"0.3.0":"2026-09-30T14:00:00Z","0.4.0":"2026-10-26T16:00:00Z"},"left-pad":{"1.3.0":"2018-04-09T00:00:00Z"},"pino":{"9.12.0":"2026-10-23T11:00:00Z","9.12.1":"2026-10-24T11:00:00Z"}},"changes":[{"name":"zod","from":"4.1.11","to":"4.1.12"},{"name":"left-pad","from":null,"to":"1.3.0"},{"name":"pino","from":"9.12.0","to":"9.12.1"},{"name":"@codedev/md-render","from":null,"to":"0.3.0"}]}', '"allow zod@4.1.12 (was 4.1.11): exception SEC-212 (expires 2026-11-03)\nblock left-pad@1.3.0: not on allowlist; exception SEC-118 not valid (expires 2026-10-20)\nblock pino@9.12.1 (was 9.12.0): quarantined until 2026-10-31 (published 2026-10-24)\nallow @codedev/md-render@0.3.0\n2 allowed, 2 blocked"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'Day boundaries: quarantine ending today, UTC dates of +07:00 and 23:59Z, future dates, expiry today', '{"today":"2026-10-27","policy":{"allowlist":["a-ends-today","b-ends-tomorrow","c-offset","d-late-utc","e-future","g-zero-hour"],"quarantineDays":7,"exceptions":[{"name":"f-expires-today","version":"1.0.0","ticket":"SEC-301","expires":"2026-10-27"},{"name":"h-expired-yesterday","version":"1.0.0","ticket":"SEC-302","expires":"2026-10-26"}]},"registry":{"a-ends-today":{"1.0.0":"2026-10-20T00:00:00Z"},"b-ends-tomorrow":{"1.0.0":"2026-10-21T00:00:00Z"},"c-offset":{"1.0.0":"2026-10-21T03:00:00+07:00"},"d-late-utc":{"1.0.0":"2026-10-20T23:59:59Z"},"e-future":{"1.0.0":"2026-10-29T08:00:00Z"},"f-expires-today":{"1.0.0":"2026-10-26T08:00:00Z"},"g-zero-hour":{"2.0.0":"2026-10-21T00:30:00.000+01:00"},"h-expired-yesterday":{"1.0.0":"2025-01-01T00:00:00Z"}},"changes":[{"name":"a-ends-today","from":null,"to":"1.0.0"},{"name":"b-ends-tomorrow","from":null,"to":"1.0.0"},{"name":"c-offset","from":null,"to":"1.0.0"},{"name":"d-late-utc","from":null,"to":"1.0.0"},{"name":"e-future","from":null,"to":"1.0.0"},{"name":"f-expires-today","from":null,"to":"1.0.0"},{"name":"g-zero-hour","from":"1.9.0","to":"2.0.0"},{"name":"h-expired-yesterday","from":null,"to":"1.0.0"}]}', '"allow a-ends-today@1.0.0\nblock b-ends-tomorrow@1.0.0: quarantined until 2026-10-28 (published 2026-10-21)\nallow c-offset@1.0.0\nallow d-late-utc@1.0.0\nblock e-future@1.0.0: quarantined until 2026-11-05 (published 2026-10-29)\nallow f-expires-today@1.0.0: exception SEC-301 (expires 2026-10-27)\nallow g-zero-hour@2.0.0 (was 1.9.0)\nblock h-expired-yesterday@1.0.0: not on allowlist; exception SEC-302 not valid (expires 2026-10-26)\n5 allowed, 3 blocked"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'Allowlist patterns: other scopes that start like ours, prefixes of exact names, case', '{"today":"2026-10-27","policy":{"allowlist":["@codedev/*","lodash","@types/*","@babel/core","express","@codedev"],"quarantineDays":7,"exceptions":[]},"registry":{"@codedev/ui":{"2.0.0":"2026-01-10T00:00:00Z"},"@codedev-labs/grader":{"1.0.0":"2026-01-10T00:00:00Z"},"@codedevs/ui":{"2.0.0":"2026-01-10T00:00:00Z"},"codedev-utils":{"1.0.0":"2026-01-10T00:00:00Z"},"lodash":{"4.17.21":"2021-02-20T15:42:16Z"},"lodash.merge":{"4.6.2":"2019-07-04T00:00:00Z"},"lodash-es":{"4.17.21":"2021-02-20T15:42:16Z"},"@types/node":{"24.9.1":"2026-10-01T00:00:00Z"},"@babel/core":{"7.28.4":"2026-09-01T00:00:00Z"},"@babel/parser":{"7.28.4":"2026-09-01T00:00:00Z"},"Express":{"4.21.2":"2024-12-05T17:20:31Z"},"@codedev/sub/x":{"1.0.0":"2026-01-10T00:00:00Z"}},"changes":[{"name":"@codedev/ui","from":"1.9.0","to":"2.0.0"},{"name":"@codedev-labs/grader","from":null,"to":"1.0.0"},{"name":"@codedevs/ui","from":null,"to":"2.0.0"},{"name":"codedev-utils","from":null,"to":"1.0.0"},{"name":"lodash","from":null,"to":"4.17.21"},{"name":"lodash.merge","from":null,"to":"4.6.2"},{"name":"lodash-es","from":null,"to":"4.17.21"},{"name":"@types/node","from":"24.9.0","to":"24.9.1"},{"name":"@babel/core","from":null,"to":"7.28.4"},{"name":"@babel/parser","from":null,"to":"7.28.4"},{"name":"Express","from":null,"to":"4.21.2"}]}', '"allow @codedev/ui@2.0.0 (was 1.9.0)\nblock @codedev-labs/grader@1.0.0: not on allowlist\nblock @codedevs/ui@2.0.0: not on allowlist\nblock codedev-utils@1.0.0: not on allowlist\nallow lodash@4.17.21\nblock lodash.merge@4.6.2: not on allowlist\nblock lodash-es@4.17.21: not on allowlist\nallow @types/node@24.9.1 (was 24.9.0)\nallow @babel/core@7.28.4\nblock @babel/parser@7.28.4: not on allowlist\nblock Express@4.21.2: not on allowlist\n4 allowed, 7 blocked"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'Invalid data fails closed: unreadable dates, unreal expiry dates, exceptions for missing versions', '{"today":"2026-10-27","policy":{"allowlist":["@codedev/*","pino","zod","marked"],"quarantineDays":7,"exceptions":[{"name":"pino","version":"9.13.0","ticket":"SEC-401","expires":"2026-12-01"},{"name":"zod","version":"4.2.0","ticket":"SEC-402","expires":"2026-02-30"},{"name":"zod","version":"4.2.0","ticket":"SEC-403","expires":"soon"},{"name":"marked","version":"15.0.0","ticket":"SEC-404","expires":"2026-11-30"},{"name":"ghost-lib","version":"1.0.0","ticket":"SEC-405","expires":"2026-11-30"},{"name":"chalk","version":"5.6.2","ticket":"SEC-406","expires":"2026-13-01"}]},"registry":{"pino":{"9.12.1":"2026-10-01T00:00:00Z"},"zod":{"4.2.0":"2026-10-26T00:00:00Z"},"marked":{"15.0.0":"yesterday","15.0.1":"","15.0.2":"2026-10-01"},"@codedev/ui":{"3.0.0":"Mon, 26 Oct 2026 10:00:00 GMT"},"chalk":{"5.6.2":"2026-01-01T00:00:00Z"}},"changes":[{"name":"pino","from":"9.12.1","to":"9.13.0"},{"name":"zod","from":"4.1.12","to":"4.2.0"},{"name":"marked","from":"14.1.2","to":"15.0.0"},{"name":"marked","from":"14.1.2","to":"15.0.1"},{"name":"marked","from":"14.1.2","to":"15.0.2"},{"name":"@codedev/ui","from":"2.0.0","to":"3.0.0"},{"name":"ghost-lib","from":null,"to":"1.0.0"},{"name":"chalk","from":null,"to":"5.6.2"}]}', '"block pino@9.13.0 (was 9.12.1): not in registry\nblock zod@4.2.0 (was 4.1.12): quarantined until 2026-11-02 (published 2026-10-26); exception SEC-402 not valid (expires 2026-02-30)\nblock marked@15.0.0 (was 14.1.2): publish date unknown\nblock marked@15.0.1 (was 14.1.2): publish date unknown\nblock marked@15.0.2 (was 14.1.2): publish date unknown\nblock @codedev/ui@3.0.0 (was 2.0.0): publish date unknown\nblock ghost-lib@1.0.0: not in registry; not on allowlist\nblock chalk@5.6.2: not on allowlist; exception SEC-406 not valid (expires 2026-13-01)\n0 allowed, 8 blocked"', 3, false, tru