       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_132'), 'Quarantine of 0 days: only a version dated after today is held', '{"today":"2026-10-27","policy":{"allowlist":["zod","pino"],"quarantineDays":0,"exceptions":[]},"registry":{"zod":{"4.1.12":"2026-10-27T23:00:00Z"},"pino":{"9.13.0":"2026-10-28T00:00:00Z"}},"changes":[{"name":"zod","from":"4.1.11","to":"4.1.12"},{"name":"pino","from":null,"to":"9.13.0"}]}', '"allow zod@4.1.12 (was 4.1.11)\nblock pino@9.13.0: quarantined until 2026-10-28 (published 2026-10-28)\n1 allowed, 1 blocked"', 2, false, true, 6),
