-- challenge chal_coding_ssc_212 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_212', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-2-1' AND is_deleted = false LIMIT 1), 'scoped-name-checker', 'Fix the dependency checker that skipped scoped names', 'An AI assistant added "@codedev-ui/form-utils" to CodeDev''s package.json. CodeDev owns the npm scope @codedev, not @codedev-ui. The CI step check-deps logged "owned scope, skipped: @codedev-ui/form-utils" and "41 dependencies, 36 checked, 0 not found: PASS"; three days later a stranger registered @codedev-ui and published a version whose postinstall script read the build''s environment variables. Fix checkDependencies(dependencies, policy, registry) so that it returns exactly one finding per entry of dependencies, in input order: { dependency, package, status }. dependency is the key in package.json. package is the package npm installs: the key itself, or for an alias ("key": "npm:<name>@<range>", or "npm:<name>" without a range) the <name> after "npm:" - a scoped name starts with "@", so the "@" before the range is the first "@" after the first character; package is "" when the status is invalid. status is the first rule that applies: "invalid" when the key or the package is not a valid name (valid: "<part>" or "@<part>/<part>", where <part> starts with a-z or 0-9 and continues with a-z 0-9 . _ -, at most 214 characters in total); "unknown_scope" when the package is scoped and its scope (the text before the first "/", e.g. "@codedev") is not one of policy.ownedScopes or policy.knownScopes, compared as whole strings; "not_found" when the package is not in the registry snapshot (a list of names; scoped packages of owned or known scopes are looked up too); otherwise "ok". The range part of a spec is not checked. The runner reads { ownedScopes, knownScopes, registry, dependencies } and prints the findings as JSON.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
