-- challenge chal_quiz_ssc_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ssc_221', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-2-2' AND is_deleted = false LIMIT 1), 'typosquat-distance-quiz', 'One edit away: read the detector''s output', 'Two findings from CodeDev''s typosquat detector: why a swapped pair of letters needs Damerau-Levenshtein, and what a distance of 0 after normalization does and does not mean.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_221'), 'The typosquat detector on PR #1207 compares the normalized candidate with each popular name. Threshold for a normalized name of 4 to 7 characters: 1.

candidate   popular   Levenshtein   Damerau-Levenshtein (OSA)
reqeust     request   2             1
lodahs      lodash    2             1

Detector output (Damerau-Levenshtein):
{"name":"lodahs","nearest":"lodash","distance":1,"verdict":"lookalike"}
{"name":"reqeust","nearest":"request","distance":1,"verdict":"lookalike"}

Statement: "If the detector used plain Levenshtein distance with the same thresholds, it would report reqeust and lodahs as clear."', 'single_choice'::question_type, 'True. Plain Levenshtein has no swap operation, so turning "eq" into "qe" costs two substitutions (or a delete and an insert): distance 2, above the threshold of 1 for a 7-character name, so the verdict would be clear. Swapped adjacent letters are among the most common typing mistakes, and therefore among the most common typosquats; Damerau-Levenshtein counts the swap as one edit. The misconception is that any edit distance will do: the choice of operations decides which mistakes you catch at a given threshold.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_221'), 'Detector output on PR #1207, popular list ["lodash", "react", "request", ...]:

{"name":"l0dash-js","nearest":"lodash","distance":0,"verdict":"lookalike"}

normalize("l0dash-js"): "l0dash-js" -> digit swap -> "lodash-js" -> trailing "-js" removed -> "lodash"

Statement: "A distance of 0 means l0dash-js and lodash are the same package on the registry, so the verdict should be exact instead of lookalike."', 'single_choice'::question_type, 'False. Normalization exists only to compare names the way a hurried human reads them; the registry compares exact strings. l0dash-js is a different package, published by whoever registered it, and a distance of 0 after normalization is the strongest typosquat signal there is: the name was built to look like lodash. Exact must compare the raw name with the popular list. The misconception is to treat a normalized match as identity, which turns the detector''s best catch into an approval.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_ssc_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_222', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-2-2' AND is_deleted = false LIMIT 1), 'typosquat-detector', 'Typosquat detector', 'Before a PR that adds dependencies can merge, CodeDev compares every new package name with a list of popular names: "reqeust", "crossenv" and "L0dash.js" are one edit or one trick away from packages everyone installs. Write detectTyposquats(popular, candidates), which returns one { name, nearest, distance, verdict } per candidate. verdict "invalid": the candidate is "", longer than 214 characters, or contains a character other than A-Z a-z 0-9 @ / . _ ~ - (nearest null, distance null). "exact": the candidate is exactly, same case, one of the popular names (nearest = the candidate, distance 0). Otherwise normalize the candidate and every popular name and compute the distance between the normalized forms; nearest = the popular name as written in the list with the smallest distance (on a tie, the popular name that sorts first with < and >); verdict "lookalike" when distance <= threshold(length of the normalized candidate), else "clear". normalize, in this order: (1) lowercase; (2) "@scope/rest" becomes "rest" (only when the name starts with "@" and contains "/"); (3) every "_" and "." becomes "-"; (4) every "1" becomes "l" and every "0" becomes "o"; (5) remove a leading "js-", then a trailing "-js", each only when something is left. distance: Damerau-Levenshtein in its restricted form (optimal string alignment): the fewest inserts, deletes, substitutions and swaps of two adjacent characters, each costing 1, with no character edited twice. threshold(n): 0 for n <= 3, 1 for 4 <= n <= 7, 2 for n >= 8. Sort the results by verdict (lookalike, invalid, clear, exact), then by distance (smallest first), then by name (< and >); equal results keep their input order. The runner reads { popular, candidates } (popular has at least one name) and prints the results as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222'), 1, 'Which two strings are the same package for npm, and which two only look the same to a hurried reader? Exact must answer the first question with the raw name; the distance answers the second with normalized names.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222'), 2, 'Build and test the three pieces separately before detectTyposquats: normalize (five steps, in the order given), the distance table (insert, delete and substitute, plus one extra case for two adjacent characters that are swapped, which looks two rows and two columns back), and the threshold, which uses the length of the normalized candidate. Then check the sort keys: verdict, distance, name.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222'), 3, 'A similar case with other names: popular ["chalk", "qs"]. "hcalk" has "ch" swapped: distance 1 (plain Levenshtein says 2); its normalized length is 5, so the threshold is 1 and it is a lookalike of chalk. "chalk.js" becomes "chalk-js", then "chalk": distance 0, a lookalike, not exact, because the raw name differs. "q-s" stays "q-s": length 3, threshold 0, distance 1 from "qs", so it is clear with nearest "qs".');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_222'), 'The PR''s suggestions: a swap, a separator trick, a scope clone, a missing letter, an exact match', '{"popular":["react","react-dom","lodash","express","request","cross-env","dompurify","zod","qs","ms","chalk","axios","js-yaml","yaml","@types/node","typescript","next","i18next","uuid","pg","ws"],"candidates":["reqeust","cross_env","@codedev-ui/lodash","react","zod-validation-kit","dompurfy"]}', '[{"name":"@codedev-ui/lodash","nearest":"lodash","distance":0,"verdict":"lookalike"},{"name":"cross_env","nearest":"cross-env","distance":0,"verdict":"lookalike"},{"name":"dompurfy","nearest":"dompurify","distance":1,"verdict":"lookalike"},{"name":"reqeust","nearest":"request","distance":1,"verdict":"lookalike"},{"name":"zod-validation-kit","nearest":"axios","distance":15,"verdict":"clear"},{"name":"react","nearest":"react","distance":0,"verdict":"exact"}]', 3, true, false, 1),
