-- challenge chal_quiz_ssc_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ssc_231', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-2-3' AND is_deleted = false LIMIT 1), 'install-scripts-quiz', 'Which install scripts run?', 'Two pieces of CodeDev''s install pipeline: what --ignore-scripts plus a reviewed rebuild list does to a new package''s postinstall, and whether an allowlisted name may run a new version''s script.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_231'), 'CI install job of the CodeDev web app:

- run: npm ci --ignore-scripts
- run: npm rebuild bcrypt sharp     # the packages planInstallScripts allowed: reviewed name, version and integrity

package-lock.json in the PR under test:
"node_modules/progress-reporter-x": {
  "version": "0.2.0",
  "resolved": "https://registry.npmjs.org/progress-reporter-x/-/progress-reporter-x-0.2.0.tgz",
  "hasInstallScript": true
}

Statement: "In this job the postinstall script of progress-reporter-x does not run, while bcrypt and sharp still build their native code."', 'single_choice'::question_type, 'True. --ignore-scripts stops npm ci from running any lifecycle script, from every dependency and from the project itself, so the new package''s postinstall never runs. npm rebuild then runs the install scripts only of the packages named on its command line, which here come from the reviewed allowlist. The misconception is that blocking scripts must break native modules: they still build, but only the ones someone reviewed. The new package''s script should still appear in the job''s report as blocked, so the PR author knows to ask for a review if it is really needed.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_231'), 'Allowlist (config/install-scripts.json), reviewed in August:
{ "name": "sharp", "version": "0.34.4", "integrity": "sha512-8b4c...e1f0", "reviewedBy": "reviewer-b" }

Dependency update PR in October, package-lock.json:
-  "node_modules/sharp": { "version": "0.34.4", "integrity": "sha512-8b4c...e1f0", "hasInstallScript": true }
+  "node_modules/sharp": { "version": "0.34.5", "integrity": "sha512-27d9...a3c5", "hasInstallScript": true }

Statement: "sharp is on the reviewed allowlist, so the install script of 0.34.5 can run without another review."', 'single_choice'::question_type, 'False. The review covered the code of sharp 0.34.4, identified by its integrity hash. 0.34.5 is new code from the registry, and a patch release is exactly what an attacker who took over a maintainer''s account would publish: in 2025 several widely used npm packages shipped malicious patch versions that way, some running their payload from an install script. Pinning the allowlist to name, version and integrity turns every version bump of a package with install scripts into a small, explicit review: diff the scripts, then add the new entry. The misconception is to trust a name; trust belongs to reviewed bytes.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_ssc_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_232', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-2-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-install-scripts', 'Spot the AI Mistake: install scripts allowed by default', 'CodeDev''s CI ran npm ci --ignore-scripts and then npm rebuild for the packages that planInstallScripts allowed. After sharp was added the build failed, and an AI assistant was asked: "make the CI install step faster and stop the native module build failing". It merged the steps into npm ci --foreground-scripts --unsafe-perm (the team has reverted that line) and rewrote planInstallScripts; the build is green and the public tests pass. Fix planInstallScripts(lock, allowlist) so that it follows CodeDev''s install policy and returns { run, blocked }. Scripts that count, when present with a non-empty value: preinstall, install, postinstall for registry packages; the same plus prepare for git dependencies (resolved starts with "git+", "git://" or "github:"); prepare of a registry package never runs and is not reported. A script runs only when the allowlist has an entry with the same name, the same version and the same non-empty integrity as the package. Every other script is blocked with the first reason that applies: "git_dependency" (a git dependency, never allowlisted), "not_allowlisted" (no entry with this name), "version_mismatch" (entries for this name, none with this exact version; a range such as "^0.25.0" matches no version), "integrity_mismatch" (an entry with this name and version, but none with the package''s integrity, or the integrity is ""). run items are { package: "<name>@<version>", script }, blocked items add reason. Order: packages in lockfile order, then scripts in the order preinstall, install, postinstall, prepare. The runner reads { lock, allowlist } and prints the plan as JSON.', 'open', 'hard'::difficulty_question, 'fix_bug', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
