INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ssc_311', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-3-1' AND is_deleted = false LIMIT 1), 'secret-scanning-quiz', 'Is this key still a problem?', 'Two pieces of evidence from the S3 upload pull request: a key that was added and removed inside the same branch, and a scanner finding on a line that reads the environment first.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
