WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_321'), 'A step in .github/workflows/smoke.yml:

- name: Smoke test the sandbox
  env:
    SANDBOX_API_KEY: ${{ secrets.SANDBOX_API_KEY }}
  run: |
    echo "key=$SANDBOX_API_KEY"
    echo "auth=$(printf ''codedev:%s'' "$SANDBOX_API_KEY" | base64 -w0)"

Job log:
key=***
auth=Y29kZWRldjpzYnhfRkFLRV83ZjNhOWMyZTViOGQxMDQ2

Statement: "The runner masked the key on the first line, so the second line does not expose it either."', 'single_choice'::question_type, 'False. GitHub Actions masks the exact string of each registered secret wherever it appears in the log. The second line is a different string: base64 of "codedev:" plus the key, and anyone can decode it with base64 -d to get the key back. The same gap applies to any transformation - URL-encoding, JSON escaping, a substring, a value split across two lines - and to values the runner never knew were secret, such as a key read from a file during the job. The fix is not to print derived values at all (or to register them with ::add-mask:: before use) and to rotate the key, because this log has already been stored. The misconception is that masking understands the secret; it is a find-and-replace on one exact string.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_321') AND order_index = 1)
    RETURNING id
)
