WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_321'), 'Pull request #511 "Stop logging the config" changes src/config.ts:

-  console.log("loading config", config);
   if (!/^postgres(ql)?:\/\//.test(url)) {
     throw new Error(`DATABASE_URL invalid: ${url}`);
   }

src/server.ts (unchanged):
main().catch((err) => {
  console.error(err);
  process.exit(1);
});

Statement: "After this pull request, a preview deploy with a mistyped DATABASE_URL still prints the database password in the deploy log."', 'single_choice'::question_type, 'True. The thrown error carries the whole URL, including the user:password part, in its message, and the top-level handler prints the error (message and stack) with console.error, which goes to the same deploy log. Error messages also travel further than log lines: error trackers, crash reports and CI annotations copy them. The fix is to report the variable by name only ("invalid DATABASE_URL"), never its value, and to test the thrown message as well as the log output. The misconception is that secrets leak only through log statements; any string that reaches stdout or stderr, including an exception, is a log.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_321') AND order_index = 2)
    RETURNING id
)
