-- challenge chal_coding_ssc_322 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_322', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-3-2' AND is_deleted = false LIMIT 1), 'config-loader-secret-logs', 'Fix it: a config loader that prints secrets', 'src/config.ts is the first code that runs in the CodeDev API server, in next build on CI and in every preview deploy. CI build #1187 failed with "LOG_LEVEL invalid: verbose", and the line just above that error in the public build log printed the whole configuration as JSON, SANDBOX_API_KEY included. A preview deploy crashed with "DATABASE_URL invalid: postgres:/codedev_app:<password>@..." in a log the whole team can read. Even a successful start shows DATABASE_URL and SANDBOX_API_KEY in clear text.

Fix loadConfig(env, log) so that no secret value (a SCHEMA entry with secret: true) is ever logged or put in an error message. A variable is missing when it is unset or empty; defaults apply to optional ones. If any required variable is missing or any present value fails its check, log nothing and throw one Error with the message "Invalid configuration: missing A, B; invalid C" - names only, in SCHEMA order, leaving out the "missing ..." or "invalid ..." part when it is empty. Otherwise log exactly one line, "config ok: " followed by NAME=value for every SCHEMA entry in SCHEMA order, separated by single spaces: a non-secret shows its value, an optional variable that is not set shows NAME=(unset), and a secret shows "***" plus its last 4 characters when the value has 20 or more characters, or only "***" when it is shorter.

The runner reads { env }, prints every logged line as "log: <line>", then "ok" or "error: <message>", then "leaked: <NAME>" for each secret whose full value appears anywhere in that output. Do not change the schema or the test runner. Every secret in the tests is fake.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
