-- lesson 3.3: CI token permissions & dependency confusion (Sanity lesson-ssc-3-3)
UPDATE course.lesson SET title = 'CI token permissions & dependency confusion', order_index = 3, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 3 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-3-3' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 3 AND is_deleted = false LIMIT 1), 'CI token permissions & dependency confusion', 'sanity', 'lesson-ssc-3-3', 3
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-ssc-3-3' AND is_deleted = false);

