-- challenge chal_quiz_ssc_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ssc_421', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-4-2' AND is_deleted = false LIMIT 1), 'verify-digests-quiz', 'Does this gate stop a changed artifact?', 'Two pieces of evidence from the CodeDev deploy pipeline: a verification script that trusts a manifest it has not checked, and a production pod that runs different bytes than staging under the same tag.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_421'), '// scripts/verify-release.ts (deploy job)
const manifest = JSON.parse(readFileSync("release-manifest.json", "utf8"));
if (manifest.signature) {
  if (!signatureValid(KEY, canonicalManifest(manifest), manifest.signature)) fail("bad signature");
}
for (const file of readdirSync("dist")) {
  const digest = sha256Hex(readFileSync(join("dist", file)));
  if (manifest.digests[file] !== digest) fail(`${file}: digest mismatch`);
}
deploy();

release-manifest.json and dist/ are downloaded from the same artifact bucket.

Statement: "Someone who can write to the bucket but does not have the signing key cannot get a modified web.tar.gz deployed through this script."', 'single_choice'::question_type, 'False. The signature is only checked when the manifest has one. Someone with write access to the bucket replaces web.tar.gz, writes its new digest into release-manifest.json and deletes the signature field: the if is skipped, every digest matches, and deploy() runs. A missing signature must fail the same way as a wrong one, and the signature must be verified before any digest in the manifest is used. The misconception is that comparing digests proves integrity on its own: a digest only proves that the file matches the manifest, and only the signature proves who wrote the manifest.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_421'), '$ grep "set image" deploy-staging.log deploy-production.log
deploy-staging.log:    kubectl set image deploy/api api=registry.codedev.test/api:2026.10.3
deploy-production.log: kubectl set image deploy/api api=registry.codedev.test/api:2026.10.3

$ kubectl get pod -n staging -l app=api -o jsonpath=''{.items[0].status.containerStatuses[0].imageID}''
registry.codedev.test/api@sha256:4f1c2b...9d07
$ kubectl get pod -n production -l app=api -o jsonpath=''{.items[0].status.containerStatuses[0].imageID}''
registry.codedev.test/api@sha256:9b07e1...c2a4

Statement: "Staging and production run different image contents under the same tag, and deploying by digest (api@sha256:...) instead of api:2026.10.3 would make the production deploy use exactly the bytes that were tested."', 'single_choice'::question_type, 'True. A tag is a movable name: anyone who can push to the repository can point api:2026.10.3 at a new image, and each deploy resolves the tag again. The imageID of each pod shows the digest it actually runs, and here they differ, so production is not running what staging tested. A digest is the hash of the image manifest, so a reference by digest can only ever resolve to those bytes. The misconception is that a version-looking tag such as 2026.10.3 is immutable; it is only a convention, unless the registry enforces immutable tags, and even then the deploy should record the digest.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_ssc_422 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ssc_422', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-4-2' AND is_deleted = false LIMIT 1), 'verify-signed-digests', 'Deploy gate: verify artifacts against a signed manifest', 'The CodeDev release job writes a manifest with the SHA-256 digest of every artifact and signs it. The deploy job must refuse anything that does not match. In this challenge the signature is simulated with HMAC-SHA256 and a test key; real pipelines sign with Sigstore/cosign or a KMS key and verify with a public key, but the checks around the signature are the same. Write `verifyRelease(input)` with `node:crypto`.

**Input** (stdin, JSON): `{ "key": "<test key>", "artifacts": [{ "name", "content": "<base64>" }], "manifest": { "release", "digests": { "<name>": "<sha256 hex>" }, "signature": "<hex>" }, "request": { "release", "refs": ["..."] } }`. `artifacts` is the downloaded bundle, `request` is what the deploy wants to roll out.

**1. Canonical manifest.** The signed bytes are the UTF-8 string `codedev-manifest-v1\n` + `release:<release>\n` + one line `<name> sha256:<digest in lowercase>\n` per entry of `digests`, sorted by name (code unit order); every line ends with `\n`, the last one too. The manifest is **invalid** if `release` is not a non-empty string or contains `\r` or `\n`, `digests` is not an object with at least one entry, a name does not match `^[A-Za-z0-9._-]+$`, or a digest is not exactly 64 hex characters (either case). Invalid: reject with the single reason `invalid-manifest`.
**2. Signature.** Valid when `signature` is a string of exactly 64 hex characters (either case) and its bytes equal HMAC-SHA256(key as UTF-8, canonical string). Compare the two 32-byte buffers with `timingSafeEqual`. Not valid: reject with the single reason `bad-signature`; check nothing else, because none of the digests can be trusted.
**3. Everything else** (only with a valid signature; collect every reason):
- `release-mismatch` when `request.release` differs from `manifest.release`; `empty-request` when `refs` is empty.
- every artifact of the bundle: `duplicate-artifact` when its name appears more than once in the bundle (no other check for that name); else `unsigned-artifact` when the name is not in `digests`; else `digest-mismatch` when the SHA-256 (lowercase hex) of the base64-decoded content differs from the signed digest (compared in lowercase).
- every ref: without `@sha256:` it is a tag reference: `tag-reference` for the name before the last `:` (the whole ref when there is no `:`, or when `:` is its first character). With `@sha256:`, the name is the part before it and the digest the part after it (compared in lowercase): `not-in-manifest` when the name is not in `digests` (no other check for that ref); else `reference-mismatch` when the digest differs from the signed one, and `missing-artifact` when the bundle has no artifact with that name.

**Output** (one JSON object): `{ "decision": "deploy" | "reject", "reasons": [{ "artifact", "code" }], "deployed": [...] }`. `artifact` is `""` for `invalid-manifest`, `bad-signature`, `release-mismatch` and `empty-request`. Reasons are unique (same artifact and code once) and sorted by artifact, then code (code unit order). With no reason, `decision` is `deploy` and `deployed` lists `<name>@sha256:<signed digest in lowercase>` for every ref, unique and sorted; otherwise `decision` is `reject` and `deployed` is `[]`.

Up to 100 artifacts of up to 64 KB. Standard library only (`node:crypto`).', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_422');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_422'), 1, 'If someone can change both an artifact and the digest written next to it in the manifest, which check still catches them? What has to be true before you can trust any digest in the manifest?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_422'), 2, 'Look at the exact bytes you sign (lines sorted by name, digests in lowercase, a newline after every line including the last), and at what Buffer.from(signature, "hex") returns for a 63-character or non-hex signature: timingSafeEqual throws when the two buffers have different lengths.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_422'), 3, 'A similar check on other input, a webhook: the sender computes HMAC-SHA256 of the raw request body with a shared secret and sends "sha256=<hex>". The receiver strips the prefix, rejects anything that is not 64 hex characters, recomputes the HMAC over the same raw bytes (never over a re-serialized JSON object, whose key order and spacing can differ) and compares the two 32-byte buffers with timingSafeEqual.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ssc_422'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
