-- lesson 4.3: Reviewing AI-suggested dependencies before they land (Sanity lesson-ssc-4-3)
UPDATE course.lesson SET title = 'Reviewing AI-suggested dependencies before they land', order_index = 3, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 4 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-4-3' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 4 AND is_deleted = false LIMIT 1), 'Reviewing AI-suggested dependencies before they land', 'sanity', 'lesson-ssc-4-3', 3
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-ssc-4-3' AND is_deleted = false);

-- challenge chal_quiz_ssc_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ssc_431', (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'supply-chain-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ssc-4-3' AND is_deleted = false LIMIT 1), 'review-ai-dependencies-quiz', 'Review three AI-suggested dependencies', 'Three dependency suggestions from AI coding assistants in CodeDev pull requests: a package the registry does not know, a scoped package that looks like ours, and a library proposed for a format the team controls.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_431'), 'An assistant''s answer in a pull request for the grades import:
  "Use csv-stream-validator, it handles headers and types: npm install csv-stream-validator"

$ npm view csv-stream-validator
npm error code E404
npm error 404 Not Found - GET https://registry.npmjs.org/csv-stream-validator - Not found

Statement: "The suggestion should be rejected now and the name added to the team''s deny list, because anyone can register an unclaimed name later and the same suggestion can be repeated to other developers."', 'single_choice'::question_type, 'True. A 404 means the assistant invented the name. Today the install fails; tomorrow someone may register exactly that name, because invented names repeat across prompts and attackers watch for them (slopsquatting, lesson 2.2). Waiting until the package "appears" would mean installing whatever the first person to claim the name published. Rejecting it and putting the name on a deny list in the dependency check protects the next developer who gets the same answer. The misconception is that a hallucinated package is harmless because the install fails.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ssc_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
